#!/bin/bash
set -euo pipefail

# Backup current configuration
backup_config() {
    cp opencode.json opencode.json.bak
    cp env.example env.example.bak
}

# Restore backed-up configuration
restore_config() {
    cp opencode.json.bak opencode.json
    cp env.example.bak env.example
}

# Stop and remove services
stop_services() {
    docker-compose down
}

backup_config
stop_services
restore_config

# Ensure idempotence
git checkout .
git clean -fd

import http.server
import socketserver
import threading
import json
import os

PORT_OLLAMA = 11434
PORT_LITELLM = 4000

class MockOllamaHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/tags":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            response = {
                "models": [
                    {"name": "qwen2.5:1.5b-instruct-q4_K_M"}
                ]
            }
            self.wfile.write(json.dumps(response).encode("utf-8"))
        else:
            self.send_response(404)
            self.end_headers()

class MockLiteLLMHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health/liveness":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(b'{"status": "healthy"}')
        else:
            self.send_response(404)
            self.end_headers()

    def do_POST(self):
        if self.path == "/v1/chat/completions":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            response = {
                "choices": [
                    {
                        "message": {
                            "role": "assistant",
                            "content": "jack-local-coder response"
                        }
                    }
                ],
                "model": "jack-local-coder"
            }
            self.wfile.write(json.dumps(response).encode("utf-8"))
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        pass

def run_mock_servers():
    with socketserver.TCPServer(("127.0.0.1", PORT_OLLAMA), MockOllamaHandler) as httpd_ollama:
        threading.Thread(target=httpd_ollama.serve_forever, daemon=True).start()
        with socketserver.TCPServer(("127.0.0.1", PORT_LITELLM), MockLiteLLMHandler) as httpd_litellm:
            threading.Thread(target=httpd_litellm.serve_forever, daemon=True).start()
            # Keep running until signaled
            import time
            while True:
                time.sleep(1)

if __name__ == "__main__":
    run_mock_servers()

